  "titel": "string",
  "trainingsteil": "Aufwärmen|Hauptteil|Spielphase|null",
  "trainingsart": "Parkour|Gesamtgruppe|Übung mit Standzeit|Stationsübung|Partnerübung|Kleingruppe|Wettkampfform|null",
